<?php require_once 'includes/auth.php'; $pdo=db(); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); $s=$pdo->prepare('INSERT INTO leave_requests(employee_id,leave_type,starts_on,ends_on,reason) VALUES(?,?,?,?,?)'); $s->execute([(int)$_POST['employee_id'],trim($_POST['leave_type']),$_POST['starts_on'],$_POST['ends_on'],trim($_POST['reason'])]); audit('create','leave_request',(int)$pdo->lastInsertId()); flash('success','Leave request submitted.'); header('Location: leave.php'); exit;} $employees=$pdo->query("SELECT id,employee_number,job_title FROM employees WHERE status <> 'terminated' ORDER BY employee_number")->fetchAll(); $requests=$pdo->query('SELECT l.*,e.employee_number,e.job_title FROM leave_requests l JOIN employees e ON e.id=l.employee_id ORDER BY l.created_at DESC')->fetchAll(); $pageTitle='Leave management'; include 'includes/header.php'; ?><div class="dashboard-head"><div><div class="eyebrow">People operations</div><h1>Leave management</h1><p class="meta">Review time-off requests and keep capacity planning current.</p></div></div><div class="admin-grid"><form class="card form" method="post"><h2>Submit leave request</h2><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="field"><label>Employee</label><select name="employee_id" required><?php foreach($employees as $employee): ?><option value="<?= $employee['id'] ?>"><?= e($employee['employee_number'].' · '.$employee['job_title']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Leave type</label><select name="leave_type"><option>Annual leave</option><option>Sick leave</option><option>Personal leave</option><option>Parental leave</option></select></div><div class="field"><label>From</label><input type="date" name="starts_on" required></div><div class="field"><label>To</label><input type="date" name="ends_on" required></div><div class="field"><label>Reason</label><textarea name="reason" rows="3"></textarea></div><button class="btn" type="submit">Submit request</button></form><div class="card"><h2>Policy snapshot</h2><p class="meta">Default annual allowance: 20 days. Keep approvals consistent, documented, and visible to managers.</p><div class="stat"><strong><?= count(array_filter($requests, fn($r) => $r['status']==='pending')) ?></strong><span>Pending approvals</span></div></div></div><div class="card"><div class="section-head"><h2>Requests</h2><span class="meta">Latest activity</span></div><table class="table"><tr><th>Employee</th><th>Type</th><th>Dates</th><th>Status</th></tr><?php foreach($requests as $request): ?><tr><td><?= e($request['employee_number']) ?></td><td><?= e($request['leave_type']) ?></td><td><?= e($request['starts_on'].' → '.$request['ends_on']) ?></td><td><span class="pill"><?= e($request['status']) ?></span></td></tr><?php endforeach; ?></table></div><?php include 'includes/footer.php'; ?>
